        question: "\u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u062C\u0647\u062F \u0639\u0628\u0631 \u0645\u0642\u0627\u0648\u0645\u0629 10 V \u0648\u0627\u0644\u062A\u064A\u0627\u0631 \u0627\u0644\u0645\u0627\u0631 \u0641\u064A\u0647\u0627 2 A\u060C \u0641\u0645\u0627 \u0642\u064A\u0645\u0629 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629\u061F",
