        term: "\u0627\u0644\u0645\u0634\u062A\u0642\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 (First Derivative - dy/dx)",
        definition: "\u0645\u0639\u062F\u0644 \u0627\u0644\u062A\u063A\u064A\u0631 \u0627\u0644\u0644\u062D\u0638\u064A \u0644\u0644\u062F\u0627\u0644\u0629 y \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0644\u0645\u062A\u063A\u064A\u0631 x\u060C \u0648\u062A\u0645\u062B\u0644 \u0647\u0646\u062F\u0633\u064A\u064B\u0627 \u0645\u064A\u0644 \u0627\u0644\u0645\u0645\u0627\u0633 \u0644\u0645\u0646\u062D\u0646\u0649 \u0627\u0644\u062F\u0627\u0644\u0629."
