import { GoogleGenAI } from "@google/genai";
function getGeminiClient() {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey || apiKey === "MY_GEMINI_API_KEY") {
    return null;
  }
  return new GoogleGenAI({
    apiKey,
    httpOptions: {
      headers: {
        "User-Agent": "aistudio-build"
      }
    }
  });
}
function safeExtractJson(text) {
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch (_) {
  }
  let cleaned = text.trim();
  if (cleaned.startsWith("```")) {
    cleaned = cleaned.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
    try {
      return JSON.parse(cleaned);
    } catch (_) {
    }
  }
  const firstBrace = cleaned.indexOf("{");
  const lastBrace = cleaned.lastIndexOf("}");
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    const jsonSubstring = cleaned.substring(firstBrace, lastBrace + 1);
    try {
      return JSON.parse(jsonSubstring);
    } catch (_) {
      const sanitized = jsonSubstring.replace(/,\s*([\}\]])/g, "$1");
      try {
        return JSON.parse(sanitized);
      } catch (_2) {
      }
    }
  }
  return null;
}
async function callGeminiWithResilience(client, request) {
  const defaultCascade = [
    "gemini-3.1-flash-lite",
    "gemini-flash-lite-latest",
    "gemini-3.6-flash",
    "gemini-3.8-flash",
    "gemini-flash-latest"
  ];
  const models = request.preferredModel ? [request.preferredModel, ...defaultCascade] : defaultCascade;
  const uniqueModels = Array.from(new Set(models));
  let lastError = null;
  for (let i = 0; i < uniqueModels.length; i++) {
    const currentModel = uniqueModels[i];
    const maxAttempts = 2;
    for (let attempt = 1; attempt <= maxAttempts; attempt++) {
      try {
        const response = await client.models.generateContent({
          model: currentModel,
          contents: request.contents,
          config: request.config
        });
        const text = response.text?.trim() || "";
        if (text) {
          return { text, modelUsed: currentModel };
        }
      } catch (err) {
        lastError = err;
        const msg = String(err?.message || err?.status || err || "");
        const isQuotaExceeded = msg.includes("429") || msg.includes("Quota exceeded") || msg.includes("quota") || msg.includes("RESOURCE_EXHAUSTED");
        const isTemporaryBusy = msg.includes("503") || msg.includes("UNAVAILABLE") || msg.includes("high demand") || msg.includes("overloaded");
        console.warn(
          `[Gemini Resilience] Model '${currentModel}' attempt ${attempt}/${maxAttempts} failed:`,
          msg.substring(0, 160)
        );
        if (isQuotaExceeded) {
          break;
        }
        if (isTemporaryBusy && attempt < maxAttempts) {
          await new Promise((res) => setTimeout(res, 600));
          continue;
        }
        break;
      }
    }
  }
  throw lastError || new Error("All Gemini models failed to respond.");
}
